package com.naten.mobile;
import android.app.*;import android.content.*;import android.os.*;
public final class NotificationUtil { static final String CH="naten_workflow"; public static void show(Context c,String title,String text){ NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE); if(Build.VERSION.SDK_INT>=26)n.createNotificationChannel(new NotificationChannel(CH,"AutoPilot Workflows",NotificationManager.IMPORTANCE_DEFAULT)); Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CH):new Notification.Builder(c); b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(title).setContentText(text).setAutoCancel(true); if(Build.VERSION.SDK_INT<33||c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")==0)n.notify((int)(System.currentTimeMillis()%100000),b.build()); } }
